SOURCE = 'def git_push():\n    """Push commits to remote."""\n    LOGGER.debug("Running git push cwd=%s", ROOT)\n    result = run_interruptible_command(\n        ["git", "push"], ROOT, 30\n    )\n    output = result["stdout"] + result["stderr"]\n    if result["timed_out"]:\n        return "Git push timed out after 30 seconds.\\n{}".format(output)\n    if result["returncode"] != 0:\n        return "Git push failed:\\n{}".format(output)\n    return "Pushed successfully."\n\ndef load_commit_message_pattern():\n    """Return the built-in conventional commit message pattern."""\n    return DEFAULT_COMMIT_MESSAGE_PATTERN\n\n\ndef git_commit(message=None, message_only=False):\n    """Commit staged changes with the given or generated message.\n    If nothing is staged, stage all changes first.\n    If message_only is True, only generate and return the message without committing."""\n\n    # Check for staged and unstaged files\n    LOGGER.debug("Checking for staged changes cwd=%s", ROOT)\n    result = run_interruptible_command(\n        ["git", "diff", "--cached", "--name-only"], ROOT, 10\n    )\n    staged_files = result["stdout"].strip()\n\n    result = run_interruptible_command(\n        ["git", "diff", "--name-only"], ROOT, 10\n    )\n    unstaged_files = result["stdout"].strip()\n\n    # If both staged and unstaged files exist, ask user what to commit\n    if staged_files and unstaged_files:\n        print("Both staged and unstaged changes detected.")\n        print("Staged files:")\n        for f in staged_files.split("\\n"):\n            print("  {}".format(f))\n        print("Unstaged files:")\n        for f in unstaged_files.split("\\n"):\n            print("  {}".format(f))\n        print()\n        print("Commit options:")\n        print("  1) Staged only")\n        print("  2) All (stage unstaged files too)")\n        try:\n            choice = input("Choose [1/2]: ").strip()\n        except EOFError:\n            raise IterationInterrupted()\n        if choice == "2":\n            # Stage all unstaged files\n            LOGGER.debug("Staging all changes cwd=%s", ROOT)\n            result = run_interruptible_command(\n                ["git", "add", "-A"], ROOT, 10\n            )\n            output = result["stdout"] + result["stderr"]\n            if result["timed_out"]:\n                return "Git add timed out after 10 seconds.\\n{}".format(output)\n            if result["returncode"] != 0:\n                return "Git add failed:\\n{}".format(output)\n        elif choice != "1":\n            return "Invalid choice. Commit cancelled."\n\n    if message is None:\n        message = generate_commit_message()\n        if message is None:\n            return "No changes to commit."\n\n    # Ask for confirmation before committing (unless message_only)\n    if not message_only:\n        print("Commit message:")\n        print(message)\n        if not confirm_action("Commit with this message? [y/n] ", category="git_commit"):\n            return "Commit cancelled."\n\n    if message_only:\n        return message\n\n    # Check if there are staged changes (after potential staging above)\n    LOGGER.debug("Checking for staged changes cwd=%s", ROOT)\n    result = run_interruptible_command(\n        ["git", "diff", "--cached", "--name-only"], ROOT, 10\n    )\n    staged_files = result["stdout"].strip()\n    if not staged_files:\n        # Nothing staged, stage all changes\n        LOGGER.debug("No staged changes, staging all cwd=%s", ROOT)\n        result = run_interruptible_command(\n            ["git", "add", "-A"], ROOT, 10\n        )\n        output = result["stdout"] + result["stderr"]\n        if result["timed_out"]:\n            return "Git add timed out after 10 seconds.\\n{}".format(output)\n        if result["returncode"] != 0:\n            return "Git add failed:\\n{}".format(output)\n\n    LOGGER.debug("Running git commit cwd=%s", ROOT)\n    result = run_interruptible_command(\n        ["git", "commit", "-m", message], ROOT, 30\n    )\n    output = result["stdout"] + result["stderr"]\n    if result["timed_out"]:\n        return "Git commit timed out after 30 seconds.\\n{}".format(output)\n    if result["returncode"] != 0:\n        return "Git commit failed:\\n{}".format(output)\n    return "Committed: {}".format(message)\n\ndef generate_commit_message():\n    """Generate a commit message based on git status and the configured pattern.\n    First tries LLM-based generation if enabled and configured, falls back to pattern-based.\n    """\n    # Get staged and unstaged changes\n    result = run_interruptible_command(\n        ["git", "status", "--porcelain"], ROOT, 15\n    )\n    if result["timed_out"] or result["returncode"] != 0:\n        return None\n\n    changes = []\n    for line in result["stdout"].strip().split("\\n"):\n        if not line:\n            continue\n        status = line[:2]\n        filepath = line[3:]\n        changes.append((status, filepath))\n\n    if not changes:\n        return None\n\n    # Categorize changes\n    added = [f for s, f in changes if s[0] in ("A", "?")]\n    modified = [f for s, f in changes if s[0] == "M" or s[1] == "M"]\n    deleted = [f for s, f in changes if s[0] == "D" or s[1] == "D"]\n    renamed = [f for s, f in changes if s[0] == "R"]\n\n    # Determine commit type based on changes\n    commit_type = "chore"\n    if added:\n        commit_type = "feat"\n    elif modified:\n        commit_type = "fix"\n    elif deleted:\n        commit_type = "chore"\n    elif renamed:\n        commit_type = "refactor"\n\n    # Build summary\n    parts = []\n    if added:\n        parts.append("add {}".format(", ".join(added[:3])))\n    if modified:\n        parts.append("update {}".format(", ".join(modified[:3])))\n    if deleted:\n        parts.append("remove {}".format(", ".join(deleted[:3])))\n    if renamed:\n        parts.append("rename {}".format(", ".join(renamed[:3])))\n\n    summary = "; ".join(parts)\n\n    # Build changes list for + delimiter\n    all_files = [f for _, f in changes]\n    changes_str = " + ".join(all_files)\n\n    # Get the actual diff for LLM analysis\n    diff_result = run_interruptible_command(\n        ["git", "diff", "HEAD"], ROOT, 15\n    )\n    diff_content = ""\n    if not diff_result["timed_out"] and diff_result["returncode"] == 0:\n        diff_content = diff_result["stdout"].strip()\n\n    # Try LLM-based generation first (pass both file list and diff)\n    llm_message = generate_commit_message_llm(changes_str, diff_content)\n    if llm_message:\n        return llm_message\n\n    # Fall back to pattern-based generation\n    pattern = load_commit_message_pattern()\n    message = pattern.format(\n        type=commit_type,\n        summary=summary,\n        changes=changes_str,\n        added=", ".join(added) if added else "",\n        modified=", ".join(modified) if modified else "",\n        deleted=", ".join(deleted) if deleted else "",\n        renamed=", ".join(renamed) if renamed else "",\n    )\n    return message\n\ndef git_commit_push(message=None):\n    """Commit and push in one command."""\n    commit_result = git_commit(message)\n    if commit_result.startswith("Git commit failed") or commit_result.startswith("Git commit timed out") or commit_result == "Commit cancelled.":\n        return commit_result\n    push_result = git_push()\n    return "{}\\n{}".format(commit_result, push_result)\n\ndef generate_commit_message_llm(changes_summary, diff_content=""):\n    """Generate a commit message using an LLM based on the git changes summary and diff."""\n    # Commit-message model selection is configured as the commit_message role.\n    route = resolve_routed_model("commit_message", ROOT, PROVIDER, MODEL)\n    commit_provider = route["provider"]\n    commit_model = route["model"]\n    \n    # Validate provider\n    if commit_provider not in PROVIDERS:\n        LOGGER.warning(\n            "Invalid commit message provider \'%s\'; falling back to pattern-based generation.",\n            commit_provider\n        )\n        return None\n    \n    # Validate model is available for the provider\n    try:\n        available_models = get_available_models(commit_provider)\n        if commit_model not in available_models:\n            LOGGER.warning(\n                "Commit message model \'%s\' not available for provider \'%s\'; falling back to pattern-based generation.",\n                commit_model, commit_provider\n            )\n            return None\n    except Exception as error:\n        LOGGER.warning(\n            "Could not validate commit message model: %s; falling back to pattern-based generation.",\n            error\n        )\n        return None\n    \n# Build the prompt for the LLM\n    user_prompt_template = DEFAULT_COMMIT_USER_PROMPT\n\n    if diff_content:\n        diff_section = DEFAULT_COMMIT_DIFF_SECTION_WITH_DIFF.format(\n            changes=changes_summary, diff=diff_content[:8000]\n        )\n    else:\n        diff_section = DEFAULT_COMMIT_DIFF_SECTION_WITHOUT_DIFF.format(\n            changes=changes_summary\n        )\n\n    prompt = user_prompt_template.format(diff_section=diff_section)\n\n    # Prepare messages for the API call\n    messages = [\n        {"role": "system", "content": DEFAULT_COMMIT_SYSTEM_PROMPT},\n        {"role": "user", "content": prompt}\n    ]\n    try:\n        # Temporarily switch provider/model for the commit message generation\n        original_provider = PROVIDER\n        original_model = MODEL\n        \n        # We need to call the API directly with the commit message provider/model\n        # Let\'s use a simpler approach - call the provider\'s API directly\n        key = provider_api_key(commit_provider)\n        \n        # Build request body based on provider format\n        if get_provider_config(commit_provider)["format"] == "anthropic":\n            body = {\n                "model": commit_model,\n                "max_tokens": 500,\n                "system": DEFAULT_COMMIT_SYSTEM_PROMPT,\n                "messages": [{"role": "user", "content": prompt}]\n            }\n            headers = build_provider_headers(commit_provider, key)\n        else:\n            body = {\n                "model": commit_model,\n                "messages": messages,\n                "temperature": 0.2,\n                "max_tokens": 500\n            }\n            headers = build_provider_headers(commit_provider, key)\n            if commit_provider == "openai":\n                body["max_completion_tokens"] = 500\n        \n        request_data = json.dumps(body).encode("utf-8")\n        request = urllib.request.Request(\n            build_provider_url(commit_provider, "chat", key),\n            data=request_data,\n            headers=headers,\n            method="POST"\n        )\n        \n        with urllib.request.urlopen(request, timeout=provider_timeout(commit_provider, API_TIMEOUT_SECONDS)) as response:\n            raw = response.read().decode("utf-8")\n        \n        parsed = json.loads(raw)\n        \n        # Extract the response text based on provider format\n        if get_provider_config(commit_provider)["format"] == "anthropic":\n            content = parsed.get("content", [])\n            if content and isinstance(content, list):\n                for block in content:\n                    if block.get("type") == "text":\n                        return block.get("text", "").strip()\n        else:\n            choices = parsed.get("choices", [])\n            if choices:\n                message = choices[0].get("message", {})\n                return message.get("content", "").strip()\n        \n        return None\n        \n    except Exception as error:\n        LOGGER.warning(\n            "LLM commit message generation failed: %s; falling back to pattern-based generation.",\n            error\n        )\n        return None\n\ndef git_diff():\n    LOGGER.debug("Running git diff cwd=%s timeout=%ss",\n                 ROOT, TOOL_SAFEGUARDS["git_diff_timeout_seconds"])\n    result = run_interruptible_command(\n        ["git", "diff", "--"], ROOT,\n        TOOL_SAFEGUARDS["git_diff_timeout_seconds"]\n    )\n    output = result["stdout"] + result["stderr"]\n    if result["timed_out"]:\n        return "Git diff timed out after {} seconds.\\n{}".format(\n            TOOL_SAFEGUARDS["git_diff_timeout_seconds"], output\n        )\n    return output\n\ndef git_status():\n    LOGGER.debug("Running git status cwd=%s timeout=%ss",\n                 ROOT, TOOL_SAFEGUARDS["git_status_timeout_seconds"])\n    result = run_interruptible_command(\n        ["git", "status", "--short", "--branch"], ROOT,\n        TOOL_SAFEGUARDS["git_status_timeout_seconds"]\n    )\n    output = result["stdout"] + result["stderr"]\n    if result["timed_out"]:\n        return "Git status timed out after {} seconds.\\n{}".format(\n            TOOL_SAFEGUARDS["git_status_timeout_seconds"], output\n        )\n    return output\n\n'


def install(namespace):
    exec(compile(SOURCE, __file__, 'exec'), namespace)
